/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: asset, upload, rejectsWith, file, solid, chunk, pngChunks, apng, webpChunks, webpImageChunk,
 *              rgba
 *   Constants: now, hour
 * Tests
 *   - an unused upload is deletable a day after upload, a used one once its approval ends, and none before its transfer settled
 *   - an admitted upload whose transfer never started settles a transfer window after its last update
 *   - the record id is stable per administrator and intent, and the fingerprint binds every field
 *   - validation refusals keep their own codes: too large, a mismatched or unsupported type, and a truncated image
 *   - a still WebP or PNG passes the single-frame check, while an animated WebP and an APNG are refused
 *   - the single-frame check reads only PNG chunk headers before the image data and never throws on a damaged chunk list
 *   - normalization refuses undecodable bytes and an output over the limit
 *   - normalization keeps WebP lossless with exact transparent colour, or lossy, as uploaded
 *   - normalization keeps PNG pixels losslessly without growing an adaptively filtered photograph
 *   - normalization keeps JPEG chroma subsampling, the dimensions of an image without orientation, and is deterministic
 *   - normalization keeps a WebP with an extended header lossless or lossy as uploaded, keeps its transparency and drops its EXIF
 *   - normalization converts an embedded colour profile to sRGB pixels without the profile, and stores a 16-bit PNG at 8 bits
 *   - preflight refusals are catalog errors with their own status, and every non-400 refusal of these helpers is one
 *   - the upload module never imports the cover service and never uses an import helper that answers with an import error
 * @end-catalog */

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { test } from 'node:test';
import { crc32 } from 'node:zlib';
import sharp from 'sharp';
import { maxCoverArtInputBytes } from '../../src/services/image/imageStorageService';
import { AdminCatalogError } from '../../src/administration/catalog/adminCatalogService';
import type { ImportAsset } from '../../src/administration/import/adminImportMediaTypes';
import { catalogCoverUploadFingerprint, catalogCoverUploadId, catalogCoverUploadPreflight, coverUploadDeletable, coverUploadMultiFrame,
    normalizeCoverUpload, validateCatalogCoverUpload } from '../../src/administration/catalog/adminCatalogCoverUpload';

/** Every image here is generated by sharp; no file comes from a camera or a person. */
const now = new Date('2026-10-21T12:00:00.000Z'), hour = 3_600_000;
const asset = (overrides: Partial<ImportAsset> = {}): ImportAsset => ({ slotId: 'cover', operationId: '10000000-0000-4000-8000-000000000001', actorId: 'a'.repeat(24),
    bucket: 'private-imports', key: 'imports/catalog-covers/x', sha256: 'b'.repeat(64), byteLength: 3, contentType: 'image/png', filename: 'cover.png', state: 'ready',
    versionId: null, etag: '"e"', updatedAt: new Date(now.getTime() - 48 * hour), leaseOwner: null, leaseUntil: null, transferDeadline: new Date(now.getTime() - 47 * hour),
    failureConfirmedAt: null, duration: null, format: null, representation: null, tags: null, recovery: { operationId: '10000000-0000-4000-8000-000000000001', expectedRevision: 0, kind: 'upload', actorId: 'a'.repeat(24) }, ...overrides });
const upload = (ageHours: number, usedBy: string | null = null, overrides: Partial<ImportAsset> = {}) => ({ usedBy, createdAt: new Date(now.getTime() - ageHours * hour), asset: asset(overrides) });
const rejectsWith = (work: Promise<unknown>, status: number, code: string) => assert.rejects(work, (error: unknown) =>
    error instanceof AdminCatalogError && error.statusCode === status && error.code === code);
const file = (buffer: Buffer, mimetype: string) => ({ buffer, size: buffer.length, mimetype, originalname: 'cover' } as Express.Multer.File);
const solid = (width: number, height: number, background: string) => sharp({ create: { width, height, channels: 3, background } });
/** One PNG chunk with its CRC. */
const chunk = (type: string, data: Buffer) => {
    const head = Buffer.alloc(4); head.writeUInt32BE(data.length); const body = Buffer.concat([Buffer.from(type, 'latin1'), data]);
    const tail = Buffer.alloc(4); tail.writeUInt32BE(crc32(body)); return Buffer.concat([head, body, tail]);
};
/** Splits a PNG into its chunks, so tests can insert synthetic ones around the image data. */
const pngChunks = (png: Buffer) => {
    const chunks: { type: string; bytes: Buffer }[] = [];
    for (let at = 8; at + 8 <= png.length;) { const size = png.readUInt32BE(at); chunks.push({ type: png.toString('latin1', at + 4, at + 8), bytes: png.subarray(at, at + 12 + size) }); at += 12 + size; }
    return chunks;
};
/** A hand-built APNG: animation control before the image data, a second frame after it (sharp cannot write one). */
async function apng() {
    const png = await solid(4, 4, '#f80').png().toBuffer(), chunks = pngChunks(png), idat = chunks.find(item => item.type === 'IDAT')!;
    const actl = Buffer.alloc(8); actl.writeUInt32BE(2, 0); actl.writeUInt32BE(0, 4);
    const fctl = (sequence: number) => { const data = Buffer.alloc(26); data.writeUInt32BE(sequence, 0); data.writeUInt32BE(4, 4); data.writeUInt32BE(4, 8); data.writeUInt16BE(1, 20); data.writeUInt16BE(10, 22); return chunk('fcTL', data); };
    const fdat = chunk('fdAT', Buffer.concat([Buffer.from([0, 0, 0, 2]), idat.bytes.subarray(8, idat.bytes.length - 4)]));
    return Buffer.concat([png.subarray(0, 8), ...chunks.flatMap(item => item.type === 'IDAT' ? [chunk('acTL', actl), fctl(0), item.bytes, fctl(1), fdat] : [item.bytes])]);
}
/** The chunk types of a WebP, in order. */
const webpChunks = (webp: Buffer) => {
    const types: string[] = [];
    for (let at = 12; at + 8 <= webp.length;) { const size = webp.readUInt32LE(at + 4); types.push(webp.toString('latin1', at, at + 4)); at += 8 + size + (size & 1); }
    return types;
};
/** The first image chunk of a WebP (`VP8 ` or `VP8L`). */
const webpImageChunk = (webp: Buffer) => webpChunks(webp).find(type => type === 'VP8 ' || type === 'VP8L') ?? null;
const rgba = async (image: Buffer) => sharp(image).ensureAlpha().raw().toBuffer();

test('an unused upload is deletable a day after upload, a used one once its approval ends, and none before its transfer settled', () => {
    assert.equal(coverUploadDeletable(upload(23), null, now), false);
    assert.equal(coverUploadDeletable(upload(24), null, now), true);
    const used = upload(1, 'c'.repeat(24));
    for (const operation of [{ state: 'copying', cleanupPending: false }, { state: 'needsAttention', cleanupPending: true }, { state: 'cancelled', cleanupPending: true }, null])
        assert.equal(coverUploadDeletable(used, operation, now), false, JSON.stringify(operation));
    for (const operation of [{ state: 'complete', cleanupPending: true }, { state: 'complete', cleanupPending: false }, { state: 'cancelled', cleanupPending: false }])
        assert.equal(coverUploadDeletable(used, operation, now), true, JSON.stringify(operation));
    // An unsettled transfer may still land an object, so absence proves nothing yet.
    assert.equal(coverUploadDeletable(upload(48, null, { state: 'unknown', transferDeadline: new Date(now.getTime() + 60_000) }), null, now), false);
    assert.equal(coverUploadDeletable(upload(48, null, { leaseUntil: new Date(now.getTime() + 60_000) }), null, now), false);
    assert.equal(coverUploadDeletable(upload(48, 'c'.repeat(24), { state: 'unknown', transferDeadline: new Date(now.getTime() + 60_000) }), { state: 'complete', cleanupPending: false }, now), false);
});

test('an admitted upload whose transfer never started settles a transfer window after its last update', () => {
    const admitted = (updatedAgoMs: number) => upload(48, null, { state: 'pending', etag: null, transferDeadline: null, updatedAt: new Date(now.getTime() - updatedAgoMs) });
    assert.equal(coverUploadDeletable(admitted(179_999), null, now), false);
    assert.equal(coverUploadDeletable(admitted(180_000), null, now), true);
});

test('the record id is stable per administrator and intent, and the fingerprint binds every field', () => {
    const actor = 'a'.repeat(24), key = '10000000-0000-4000-8000-000000000001';
    const id = catalogCoverUploadId(actor, key);
    assert.match(id, /^[0-9a-f]{24}$/); assert.equal(catalogCoverUploadId(actor, key), id);
    assert.notEqual(catalogCoverUploadId('b'.repeat(24), key), id); assert.notEqual(catalogCoverUploadId(actor, '20000000-0000-4000-8000-000000000002'), id);
    const base = { kind: 'album', ownerId: 'c'.repeat(24), sha256: 'd'.repeat(64), byteLength: 10, contentType: 'image/png', filename: 'cover.png' }, print = catalogCoverUploadFingerprint(base);
    assert.equal(catalogCoverUploadFingerprint({ ...base }), print);
    for (const change of [{ kind: 'artist' }, { ownerId: 'e'.repeat(24) }, { sha256: 'f'.repeat(64) }, { byteLength: 11 }, { contentType: 'image/webp' }, { filename: 'other.png' }])
        assert.notEqual(catalogCoverUploadFingerprint({ ...base, ...change }), print, JSON.stringify(change));
});

test('validation refusals keep their own codes: too large, a mismatched or unsupported type, and a truncated image', async () => {
    await rejectsWith(validateCatalogCoverUpload({ size: maxCoverArtInputBytes + 1, buffer: Buffer.alloc(1), mimetype: 'image/png' } as Express.Multer.File), 413, 'ADMIN_CATALOG_COVER_TOO_LARGE');
    const png = await solid(4, 4, '#08f').png().toBuffer(), jpeg = await solid(64, 64, '#08f').jpeg().toBuffer();
    await rejectsWith(validateCatalogCoverUpload(file(png, 'image/jpeg')), 400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE');
    await rejectsWith(validateCatalogCoverUpload(file(png, 'image/gif')), 400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE');
    await rejectsWith(validateCatalogCoverUpload(file(jpeg.subarray(0, jpeg.length - 40), 'image/jpeg')), 400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE');
    await validateCatalogCoverUpload(file(png, 'image/png'));
});

test('a still WebP or PNG passes the single-frame check, while an animated WebP and an APNG are refused', async () => {
    const red = await solid(8, 8, '#f00').png().toBuffer(), blue = await solid(8, 8, '#00f').png().toBuffer();
    const still = await sharp(red).webp().toBuffer(), animated = await sharp([red, blue], { join: { animated: true } }).webp().toBuffer(), animatedPng = await apng();
    assert.equal(await coverUploadMultiFrame(still, 'image/webp'), false);
    assert.equal(await coverUploadMultiFrame(animated, 'image/webp'), true);
    assert.equal(await coverUploadMultiFrame(red, 'image/png'), false);
    assert.equal(await coverUploadMultiFrame(animatedPng, 'image/png'), true);
    assert.equal(await coverUploadMultiFrame(Buffer.from('not a webp'), 'image/webp'), true);
    // libvips reads the APNG as one still frame, which is why the explicit check exists.
    assert.equal((await sharp(animatedPng).metadata()).pages ?? 1, 1);
    await rejectsWith(validateCatalogCoverUpload(file(animated, 'image/webp')), 400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE');
    await rejectsWith(validateCatalogCoverUpload(file(animatedPng, 'image/png')), 400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE');
    await validateCatalogCoverUpload(file(still, 'image/webp'));
});

test('the single-frame check reads only PNG chunk headers before the image data and never throws on a damaged chunk list', async () => {
    const png = await solid(4, 4, '#f80').png().toBuffer(), header = png.subarray(0, 33);
    assert.equal(await coverUploadMultiFrame(header, 'image/png'), false);
    const oversized = Buffer.from(header); oversized.writeUInt32BE(0xffffffff, 8);
    assert.equal(await coverUploadMultiFrame(oversized, 'image/png'), false);
    // Animation control after the first image data chunk is not an APNG.
    const idat = png.indexOf('IDAT') - 4, after = idat + 12 + png.readUInt32BE(idat), actl = Buffer.alloc(8); actl.writeUInt32BE(2, 0);
    assert.equal(await coverUploadMultiFrame(Buffer.concat([png.subarray(0, after), chunk('acTL', actl), png.subarray(after)]), 'image/png'), false);
    assert.equal(await coverUploadMultiFrame(await solid(4, 4, '#f80').jpeg().toBuffer(), 'image/jpeg'), false);
});

test('normalization refuses undecodable bytes and an output over the limit', async () => {
    await rejectsWith(normalizeCoverUpload(Buffer.from('synthetic bytes that are not an image'), 'image/png'), 400, 'ADMIN_CATALOG_COVER_INVALID_IMAGE');
    await rejectsWith(normalizeCoverUpload(await solid(4, 4, '#0f0').png().toBuffer(), 'image/png', 10), 413, 'ADMIN_CATALOG_COVER_TOO_LARGE');
});

test('normalization keeps WebP lossless with exact transparent colour, or lossy, as uploaded', async () => {
    const raw = Buffer.from([10, 20, 30, 0, 200, 100, 50, 255, 0, 0, 255, 255, 255, 255, 255, 255]);
    const lossless = await sharp(raw, { raw: { width: 2, height: 2, channels: 4 } }).webp({ lossless: true, exact: true }).toBuffer();
    assert.equal(webpImageChunk(lossless), 'VP8L');
    const kept = await normalizeCoverUpload(lossless, 'image/webp');
    assert.equal(webpImageChunk(kept), 'VP8L');
    assert.deepEqual([...(await rgba(kept))], [...raw]);
    const lossy = await solid(32, 32, '#a0c').webp({ quality: 80 }).toBuffer();
    assert.equal(webpImageChunk(await normalizeCoverUpload(lossy, 'image/webp')), 'VP8 ');
});

test('normalization keeps PNG pixels losslessly without growing an adaptively filtered photograph', async () => {
    const palette = await sharp(Buffer.from([255, 0, 0, 0, 255, 0, 0, 0, 255, 255, 255, 0]), { raw: { width: 2, height: 2, channels: 3 } }).png({ palette: true, colours: 4 }).toBuffer();
    assert.deepEqual([...(await rgba(await normalizeCoverUpload(palette, 'image/png')))], [...(await rgba(palette))]);
    // A synthetic photograph: a gradient with deterministic noise.
    const width = 96, height = 64, pixels = Buffer.alloc(width * height * 3); let seed = 7;
    for (let index = 0; index < pixels.length; index++) { seed = (seed * 1103515245 + 12345) >>> 0; pixels[index] = ((index % (width * 3)) + Math.floor(index / (width * 3)) * 2 + (seed >>> 28)) & 255; }
    const photo = await sharp(pixels, { raw: { width, height, channels: 3 } }).png({ adaptiveFiltering: true, compressionLevel: 9 }).toBuffer();
    const normalized = await normalizeCoverUpload(photo, 'image/png');
    assert.ok(normalized.length <= photo.length * 1.1, `${normalized.length} > 110% of ${photo.length}`);
    assert.deepEqual(await sharp(normalized).removeAlpha().raw().toBuffer(), pixels);
});

test('normalization keeps JPEG chroma subsampling, the dimensions of an image without orientation, and is deterministic', async () => {
    for (const chromaSubsampling of ['4:4:4', '4:2:0']) {
        const jpeg = await solid(32, 32, '#3a7').jpeg({ chromaSubsampling }).toBuffer();
        assert.equal((await sharp(await normalizeCoverUpload(jpeg, 'image/jpeg')).metadata()).chromaSubsampling, chromaSubsampling);
    }
    const plain = await solid(30, 20, '#123').png().toBuffer(), normalized = await normalizeCoverUpload(plain, 'image/png'), meta = await sharp(normalized).metadata();
    assert.equal(meta.width, 30); assert.equal(meta.height, 20); assert.equal(meta.format, 'png');
    const photo = await solid(40, 24, '#c84').jpeg({ quality: 70 }).toBuffer();
    assert.deepEqual(await normalizeCoverUpload(photo, 'image/jpeg'), await normalizeCoverUpload(photo, 'image/jpeg'));
});

test('normalization keeps a WebP with an extended header lossless or lossy as uploaded, keeps its transparency and drops its EXIF', async () => {
    const raw = Buffer.alloc(8 * 8 * 4);
    for (let index = 0; index < 64; index++) raw.set([index * 4, 100, 200, index % 2 ? 255 : 128], index * 4);
    const image = () => sharp(raw, { raw: { width: 8, height: 8, channels: 4 } });
    const lossyAlpha = await image().webp({ quality: 80 }).toBuffer(), losslessExif = await image().webp({ lossless: true, exact: true }).withExif({ IFD0: { Make: 'SyntheticMake' } }).toBuffer();
    assert.deepEqual(webpChunks(lossyAlpha), ['VP8X', 'ALPH', 'VP8 ']); assert.deepEqual(webpChunks(losslessExif), ['VP8X', 'VP8L', 'EXIF']);
    const lossy = await normalizeCoverUpload(lossyAlpha, 'image/webp');
    assert.equal(webpImageChunk(lossy), 'VP8 '); assert.ok(webpChunks(lossy).includes('ALPH')); assert.equal((await sharp(lossy).metadata()).hasAlpha, true);
    const lossless = await normalizeCoverUpload(losslessExif, 'image/webp');
    assert.equal(webpImageChunk(lossless), 'VP8L'); assert.equal(webpChunks(lossless).includes('EXIF'), false); assert.equal(lossless.includes('SyntheticMake'), false);
    assert.equal((await sharp(lossless).metadata()).exif, undefined);
    assert.deepEqual(await sharp(lossless).raw().toBuffer(), raw);
});

test('normalization converts an embedded colour profile to sRGB pixels without the profile, and stores a 16-bit PNG at 8 bits', async () => {
    // The pixels as stored in the file, without applying any embedded profile.
    const stored = async (image: Buffer) => [...(await sharp(image, { ignoreIcc: true }).raw().toBuffer()).subarray(0, 3)];
    const encoders = [['image/png', (image: ReturnType<typeof sharp>) => image.png()], ['image/jpeg', (image: ReturnType<typeof sharp>) => image.jpeg({ quality: 100 })], ['image/webp', (image: ReturnType<typeof sharp>) => image.webp({ lossless: true })]] as const;
    for (const [type, encode] of encoders) {
        // A pure sRGB green written in Display P3, whose stored values differ from sRGB's.
        const tagged = await encode(solid(4, 4, '#00ff00')).withIccProfile('p3').toBuffer(), [red, , blue] = await stored(tagged);
        assert.ok((await sharp(tagged).metadata()).icc); assert.ok(red > 60 && blue > 30, `${type} input ${[red, blue]}`);
        const normalized = await normalizeCoverUpload(tagged, type), meta = await sharp(normalized).metadata(), [r, g, b] = await stored(normalized);
        assert.equal(meta.icc, undefined, type); assert.equal(meta.space, 'srgb', type);
        assert.ok(r <= 8 && g >= 247 && b <= 8, `${type} output ${[r, g, b]}`);
    }
    const deep = await solid(6, 4, '#357').toColourspace('rgb16').png().toBuffer();
    assert.equal((await sharp(deep).metadata()).depth, 'ushort');
    const meta = await sharp(await normalizeCoverUpload(deep, 'image/png')).metadata();
    assert.deepEqual([meta.format, meta.depth, meta.width, meta.height], ['png', 'uchar', 6, 4]);
});

test('preflight refusals are catalog errors with their own status, and every non-400 refusal of these helpers is one', async () => {
    const saved = process.env.S3_BUCKET_NAME, ready = process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY, key = '10000000-0000-4000-8000-000000000001';
    try {
        process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY = 'true';
        assert.equal(catalogCoverUploadPreflight('album', 'a'.repeat(24), key), 'album');
        delete process.env.S3_BUCKET_NAME;
        assert.throws(() => catalogCoverUploadPreflight('album', 'a'.repeat(24), key), (error: unknown) => error instanceof AdminCatalogError && error.statusCode === 503 && error.code === 'ADMIN_IMPORT_STORAGE_UNAVAILABLE');
        assert.throws(() => catalogCoverUploadPreflight('organization', 'a'.repeat(24), key), (error: unknown) => error instanceof AdminCatalogError && error.statusCode === 400 && error.code === 'ADMIN_CATALOG_COVER_UNSUPPORTED');
        for (const [kind, id, intent] of [['playlist', 'a'.repeat(24), key], ['album', 'A'.repeat(24), key], ['album', 'a'.repeat(24), 'not-a-key'], ['album', 'a'.repeat(24), undefined]])
            assert.throws(() => catalogCoverUploadPreflight(kind, id, intent), (error: unknown) => error instanceof AdminCatalogError && error.statusCode === 400 && error.code === 'ADMIN_CATALOG_INVALID_INPUT');
    } finally {
        if (saved === undefined) delete process.env.S3_BUCKET_NAME; else process.env.S3_BUCKET_NAME = saved;
        if (ready === undefined) delete process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY; else process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY = ready;
    }
});

test('the upload module never imports the cover service and never uses an import helper that answers with an import error', () => {
    const source = readFileSync(new URL('../../src/administration/catalog/adminCatalogCoverUpload.ts', import.meta.url), 'utf8');
    assert.doesNotMatch(source, /from '\.\/adminCatalogCoverService'/);
    assert.doesNotMatch(source, /\bstorageReady\b/);
    assert.doesNotMatch(source, /AdminImportError/);
});
